export function isEdgeDispatcherAllowed(serviceName: string): boolean {
  if (!serviceName || serviceName.includes('..')) return false;
  if (EDGE_DISPATCHER_BLOCKED.has(serviceName)) return false;
  return ALLOWED.has(serviceName);
}

function base64UrlToBytes(input: string): Uint8Array {
  const padded = input.replace(/-/g, '+').replace(/_/g, '/');
  const pad = padded.length % 4 === 0 ? '' : '='.repeat(4 - (padded.length % 4));
  const binary = atob(padded + pad);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function bytesToBase64Url(bytes: ArrayBuffer): string {
  const bin = String.fromCharCode(...new Uint8Array(bytes));
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

export function isJwtVerificationEnabled(
  env: { get(key: string): string | undefined } = Deno.env,
): boolean {
  const raw = env.get('VERIFY_JWT');
  if (raw === undefined || raw === '') return true;
  const normalized = raw.trim().toLowerCase();
  return normalized !== 'false' && normalized !== '0' && normalized !== 'no';
}

export function extractBearerToken(authHeader: string | null): string | null {
  if (!authHeader) return null;
  const match = authHeader.match(/^Bearer\s+(\S+)/i);
  return match?.[1] ?? null;
}

async function verifyHs256(
  token: string,
  secret: string,
): Promise<{ ok: true } | { ok: false; reason: string }> {
  const parts = token.split('.');
  if (parts.length !== 3) return { ok: false, reason: 'invalid jwt header' };

  let header: { alg?: string; typ?: string };
  try {
    header = JSON.parse(new TextDecoder().decode(base64UrlToBytes(parts[0]))) as {
      alg?: string;
      typ?: string;
    };
  } catch {
    return { ok: false, reason: 'invalid jwt header' };
  }
  if (header.alg !== 'HS256') {
    return { ok: false, reason: 'unsupported jwt algorithm' };
  }

  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const data = new TextEncoder().encode(`${parts[0]}.${parts[1]}`);
  const sig = await crypto.subtle.sign('HMAC', key, data);
  if (bytesToBase64Url(sig) !== parts[2]) {
    return { ok: false, reason: 'invalid jwt' };
  }

  try {
    const payload = JSON.parse(new TextDecoder().decode(base64UrlToBytes(parts[1]))) as {
      exp?: number;
    };
    if (typeof payload.exp === 'number' && payload.exp * 1000 < Date.now()) {
      return { ok: false, reason: 'jwt expired' };
    }
  } catch {
    return { ok: false, reason: 'invalid jwt payload' };
  }

  return { ok: true };
}

export async function gateEdgeRequestJwt(
  req: Request,
  env: { get(key: string): string | undefined } = Deno.env,
): Promise<Response | null> {
  if (req.method === 'OPTIONS') return null;
  if (!isJwtVerificationEnabled(env)) return null;

  const secret = env.get('JWT_SECRET')?.trim();
  if (!secret) {
    return new Response(JSON.stringify({ error: 'JWT_SECRET not configured' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const token = extractBearerToken(req.headers.get('Authorization'));
  if (!token) {
    return new Response(JSON.stringify({ error: 'missing Authorization bearer token' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const verified = await verifyHs256(token, secret);
  if (!verified.ok) {
    return new Response(JSON.stringify({ error: verified.reason }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  return null;
}

EdgeRuntime: {
  userWorkers: {
    create: (opts: {
      servicePath: string;
      memoryLimitMb?: number;
      workerTimeoutMs?: number;
      noModuleCache?: boolean;
      importMapPath?: string | null;
      envVars?: Array<[string, string]>;
    }) => Promise<{ fetch: (req: Request) => Promise<Response> }>;
  };
}

function resolveServiceName(pathname: string): string | null {
  const segments = pathname.split('/').filter(Boolean);
  if (segments.length === 0) return null;
  if (segments[0] === 'functions' && segments[1] === 'v1') {
    return segments[2] ?? null;
  }
  return segments[0] ?? null;
}

function toWorkerRequest(req: Request, serviceName: string): Request {
  const url = new URL(req.url);
  const segments = url.pathname.split('/').filter(Boolean);
  let afterService: string[];
  if (segments[0] === 'functions' && segments[1] === 'v1') {
    afterService = segments.slice(3);
  } else {
    afterService = segments.slice(1);
  }
  const suffix = afterService.length > 0 ? `/${afterService.join('/')}` : '';
  url.pathname = `/functions/v1/${serviceName}${suffix}`;
  return new Request(url.toString(), req);
}
